## 4. `StudentsList.vue` — modals, `submitCourse`, grade vs course

**Important UI split**

- **新增課程:** `showCourseModal && !editingCourseId` → **`UniversalClassScheduler`** (student / teacher / subject there; submission is the scheduler’s `submit`, not `submitCourse`).
- **編輯課程:** `showCourseModal && editingCourseId` → **`CourseEditForm`** + **`submitCourse`** (teacher/subject in `CourseEditForm`).

**Edit-course modal + new-course scheduler:**

```287:320:/home/admin/frontend/src/pages/StudentsList.vue
    <!-- Edit Course Modal -->
    <div v-if="showCourseModal && editingCourseId" class="modal-overlay" @click.self="closeCourseModal">
      <div class="modal" style="width: 520px;">
        <h3>編輯課程</h3>
        <CourseEditForm
          v-model="courseForm"
          :teachers="teachers"
          :rooms="rooms"
          :subjects="SUBJECTS"
          :day-options="dayOptions"
          :time-options="TIME_OPTIONS_30"
          :settlement-day-options="settlementDayOptions"
        />

        <div class="actions">
          <button class="ghost" @click="closeCourseModal">取消</button>
          <button class="primary" @click="submitCourse">儲存</button>
        </div>
      </div>
    </div>

    <UniversalClassScheduler
      v-if="showCourseModal && !editingCourseId"
      title="新增排課（統一排課介面）"
      submit-label="建立課程並寫入堂次"
      :branch-id="props.branchId"
      :students="schedulerStudents"
      :teachers="teachers"
      :rooms="rooms"
      :initial-student-id="selectedStudentSchedulerId"
      mode="create"
      @cancel="closeCourseModal"
      @success="handleUniversalSchedulerSuccess"
    />
```

**Grade** in `StudentsList` is in the **student** modal (`studentForm.grade`), not in the course modal:

```230:234:/home/admin/frontend/src/pages/StudentsList.vue
          <div class="form-group">
            <label>年級</label>
            <select v-model="studentForm.grade">
              <option v-for="g in GRADES" :key="g.value" :value="g.value">{{ g.label }}</option>
            </select>
```

**`courseForm` + `submitCourse` (edit + legacy create branch):**  
`openAddCourse` / `editCourse` fill `courseForm` (including `subject`, `teacher_id`). `submitCourse` reads `courseForm` and `selectedStudent.value` (for `student_id` / Supabase path).

```1271:1318:/home/admin/frontend/src/pages/StudentsList.vue
const openAddCourse = (student) => {
  selectedStudent.value = student;
  editingCourseId.value = null;
  editingCourseFromLaravel.value = false;
  const today = new Date().toISOString().slice(0, 10);
  courseForm.value = {
    subject: 'Math', teacher_id: '', class_type: 'one_on_one',
    rate_per_30min: 500, duration_hours: 2, payment_type: 'session',
    sessions_purchased: 8, settlement_day: null, monthly_sessions: null,
    day_of_week: 0, days_of_week: [], day_time_slots: [], start_time: '16:00', end_time: '18:00',
    first_class_date: today, room_id: null, memo: ''
  };
  loadRoomsForBranch();
  showCourseModal.value = true;
};

const editCourse = (course) => {
  selectedStudent.value = students.value.find(s => s.id === course.student_id);
  editingCourseId.value = course.id;
  editingCourseFromLaravel.value = isLaravelCourse(course);
  courseForm.value = {
    subject: course.subject,
    teacher_id: course.teacher_id || '',
    // ...
  };
  loadRoomsForBranch();
  showCourseModal.value = true;
};
```

```1370:1510:/home/admin/frontend/src/pages/StudentsList.vue
const submitCourse = async () => {
  const form = courseForm.value;
  const student = selectedStudent.value;
  const laravelStudentId = student._laravelId ?? student.id;

  if (!editingCourseId.value) {
    if (!form.first_class_date) {
      alert('請選擇開課日');
      return;
    }
    if (form.payment_type === 'monthly' && (form.settlement_day == null || form.settlement_day < 1 || form.settlement_day > 28)) {
      alert('月結制度請選擇結算日（每月 1–28 號）');
      return;
    }
    if (!form.days_of_week || form.days_of_week.length === 0) {
      alert('請至少選擇一天固定排課');
      return;
    }
    if (!form.teacher_id) {
      alert('請選擇老師');
      return;
    }
    try {
      const { data: { session: sess } } = await supabase.auth.getSession();
      const token = sess?.access_token;
      if (!token) {
        alert('請重新登入後再試');
        return;
      }
      const body = {
        student_id: laravelStudentId,
        subject: form.subject,
        teacher_id: form.teacher_id,
        class_type: form.class_type,
        // ...
        Memo: form.memo || null
      };
      const res = await fetch('/api/v1/student-classes', {
        method: 'POST',
        // ...
        body: JSON.stringify(body)
      });
      // ...
    } catch (e) {
      // ...
    }
  }

  if (editingCourseFromLaravel.value) {
    try {
      // ...
      const body = {
        subject: form.subject,
        teacher_id: form.teacher_id || null,
        class_type: form.class_type,
        // ...
      };
      const res = await fetch(`/api/v1/student-classes/${editingCourseId.value}`, {
        method: 'PUT',
        // ...
        body: JSON.stringify(body)
      });
      // ...
    } catch (_) {}
  }
  const base = {
    student_id: student.id,
    branch_id: props.branchId,
    subject: form.subject,
    teacher_id: form.teacher_id || null,
    // ... supabase fallback update ...
  };
```

